    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0x87AEBCACC72E06E9ULL + 0x85C657C754E5A805ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xD60CA66D7CF88341ULL + 0xD359891C6AD56D41ULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseB(pNonce * 0x970EADCBDCE961FFULL + 0xC8C8050A948683F2ULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0xF9304A49D0065883ULL + 0xC92118CE2E75AFC3ULL);
    const std::uint64_t aNonceWordE = TwistMix64::DiffuseA(pNonce * 0xA53CF50F25454D13ULL + 0xDF97337C1C1CE1E1ULL);
    const std::uint64_t aNonceWordF = TwistMix64::DiffuseB(pNonce * 0xA31BCBE9230DDA43ULL + 0xD7C7525D96476440ULL);
    const std::uint64_t aNonceWordG = TwistMix64::DiffuseA(pNonce * 0x885575D0B3E23405ULL + 0xACEB29A8EE188BC8ULL);
    const std::uint64_t aNonceWordH = TwistMix64::DiffuseA(pNonce * 0xFA609E6D2AEA01B9ULL + 0xCC7A34E7E981BBDDULL);
