    const std::uint64_t aNonceWordJ = TwistMix64::DiffuseC(pNonce * 0xF4110ACB54A9A51BULL + 0xE233517A0BE256DEULL);
    const std::uint64_t aNonceWordK = TwistMix64::DiffuseA(pNonce * 0xD42A7FCE3CBB9A07ULL + 0x89B10BA90B5DD02AULL);
    const std::uint64_t aNonceWordL = TwistMix64::DiffuseC(pNonce * 0x96A5FC6465A162F5ULL + 0x924174D6174AADC1ULL);
    const std::uint64_t aNonceWordM = TwistMix64::DiffuseC(pNonce * 0xA75B0D0E6A0FAAA7ULL + 0xD91811143C6DC171ULL);
    const std::uint64_t aNonceWordN = TwistMix64::DiffuseC(pNonce * 0xD6AA5D96009454B3ULL + 0xB2CE3237438EEA5AULL);
    const std::uint64_t aNonceWordO = TwistMix64::DiffuseA(pNonce * 0xC723ABB7CD4B5DBFULL + 0xDD2C6BE6EF284381ULL);
    const std::uint64_t aNonceWordP = TwistMix64::DiffuseC(pNonce * 0xA78EF6F87524B42FULL + 0xD7F09D67A2DC3205ULL);
