            aCross = RotL64(aNonceLane[((S_BLOCK1 - aIndex + 4290U)) & S_BLOCK1], 37U) ^ RotL64(aSource[((S_BLOCK1 - aIndex + 5163U)) & S_BLOCK1], 14U);
            aCross = TwistMix64::DiffuseC(((aCross ^ aDomainWordCross) ^ aNonceWordJ));
            //
            aScatter = (RotL64(aCross, 3U) ^ RotL64(aPrevious, 54U)) + (RotL64(aCarry, 19U) + RotL64(aIngress, 35U));
            aScatter = TwistMix64::DiffuseA(((aScatter ^ aDomainWordScatter) ^ aNonceWordI));
            //
            aOrbiterB = (aWandererG + RotL64(aIngress, 13U)) + 0xFD0ABDF8CCC13DAEULL;
            aOrbiterD = (aWandererC + RotL64(aScatter, 58U)) + 0x6D2F1E1799C12EAAULL;
            aOrbiterH = (((aWandererB + RotL64(aPrevious, 43U)) + RotL64(aCarry, 11U)) + 0xEEA3A68D423194B7ULL) + aOASaltD[((aIndex + 305U)) & S_SALT1];
            aOrbiterG = ((aWandererH + RotL64(aCross, 5U)) + 0x50DEF43B2621E7A0ULL) + aOASaltB[((aIndex + 48U)) & S_SALT1];
            aOrbiterC = (aWandererJ + RotL64(aIngress, 51U)) + 0xAA8F1253E289EE57ULL;
            aOrbiterF = ((((aWandererF + RotL64(aScatter, 29U)) + RotL64(aCarry, 23U)) + 0x3BDEAD28851B1B2AULL) + aOASaltE[(((511U - aIndex) + 68U)) & S_SALT1]) + aNonceWordM;
            aOrbiterE = ((aWandererI + RotL64(aPrevious, 48U)) + 0xCF177EFA61A5F510ULL) + aNonceWordA;
            aOrbiterI = ((aWandererA + RotL64(aCross, 37U)) + 0x5CB099D92D2A2D0DULL) + aNonceWordK;
            aOrbiterA = (aWandererK + RotL64(aIngress, 39U)) + 0xBA13296081CCEF19ULL;
            aOrbiterJ = (((aWandererE + RotL64(aScatter, 41U)) + RotL64(aCarry, 53U)) + 0x65C30A0DEA5B383AULL) + aOASaltH[(((511U - aIndex) + 432U)) & S_SALT1];
            aOrbiterK = ((aWandererD + RotL64(aPrevious, 53U)) + 0x6C227BD76521C6BCULL) + aOASaltA[((aIndex + 403U)) & S_SALT1];
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0x4BDF6E7F3F1BC9A3ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x8BD6131BB079531CULL;
            aOrbiterH = RotL64((aOrbiterH * 0xD930671735395D41ULL), 39U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x4B21BC5B9D496C2DULL;
