            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0xBDF0CECCD64CC5E6ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0xA0CCE05881F24FCCULL;
            aOrbiterC = RotL64((aOrbiterC * 0xF6C2CA14E33D0135ULL), 21U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x54A0D073039B2E5AULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterE) ^ 0x958D4FE64906E754ULL) ^ aOUSaltD[(((511U - aIndex) + 299U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x9F644E41605ED205ULL), 29U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0xE0AA8AF0BBC72488ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0x03B67E89AFC76C76ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x87B54D44F782BA5BULL), 3U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0xF6FAC34D23E53337ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xB173B213D7D94D3EULL;
