    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSourceLane;
    READ_IN_MUTABLE_PARAMS;
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xFDAE85A548D8FFFFULL + 0xC4B2F11AD60FA697ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0x9CB1B5CCC016F1FBULL + 0xB7BE1D2820A9FDCAULL);
