    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSourceLane;
    READ_IN_MUTABLE_PARAMS;
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0x94858A32EFC7D253ULL + 0x8F7C68B8D61F4838ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0xE0D5E4F25CD3573DULL + 0x9C2B94F1F3128B0BULL);
