            aIngress ^= (RotL64(aHeartLaneA[((aIndex + 1873U)) & S_BLOCK1], 47U) ^ RotL64(aLightningLaneC[((S_BLOCK1 - aIndex + 1295U)) & S_BLOCK1], 20U));
