            //
            aOrbiterJ = (aWandererE + RotL64(aIngress, 60U)) + 0xB748A4F3CA13C32AULL;
            aOrbiterK = (aWandererK + RotL64(aScatter, 41U)) + 0x0ACEDC19F588BB62ULL;
            aOrbiterE = ((aWandererB + RotL64(aPrevious, 47U)) + RotL64(aCarry, 11U)) + 0x43A0934A79D6FEFEULL;
            aOrbiterC = (aWandererD + RotL64(aCross, 39U)) + 0xF741A910D71DF7F0ULL;
            aOrbiterB = (aWandererC + RotL64(aIngress, 53U)) + 0x8289D79299CEE2F0ULL;
