            aOrbiterG = (((aWandererI + RotL64(aPrevious, 27U)) + RotL64(aCarry, 11U)) + 0xFB9C826042C69A2EULL) + aOASaltD[(((511U - aIndex) + 458U)) & S_SALT1];
