    std::uint64_t *aOUSaltG = pWorkSpace->mDomainBundle.mKeyRotateASalts.mOrbiterUpdate.mSaltG;
    std::uint64_t *aOUSaltH = pWorkSpace->mDomainBundle.mKeyRotateASalts.mOrbiterUpdate.mSaltH;
